glsl:
vec4 effect(vec2 uv) {
  vec2 d = uv - 0.5; d.x *= uRatio;
  float r = length(d), R = 0.6;
  float k = max(0.0, 1.0 - r / R);
  float a = k * k * uAmount * 4.0 * (0.7 + 0.3 * sin(uTime));
  float s = sin(a), co = cos(a);
  d = vec2(d.x * co - d.y * s, d.x * s + d.y * co);
  d.x /= uRatio;
  return getColor(d + 0.5);
}
